import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// I shall call these... Mock Providers For Context Provision
const mockCart = {
  items: [{ id: '1', name: 'Widget', price: 29.99 }],
  total: 29.99,
  clearCart: vi.fn(),
};
const mockProcessPayment = vi.fn();

vi.mock('./CartContext', () => ({
  useCart: () => mockCart,
}));
vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment }),
}));

describe('Checkout - The Grand Purchasing Orchestrator', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-12345' });
  });

  // HAPPY PATH - Oh, how delightful when everything works!
  describe('complete checkout flow', () => {
    it('navigates through all steps to confirmation', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();
      render(<Checkout onComplete={onComplete} />);

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), '123 Elm St');
      await user.type(screen.getByLabelText(/city/i), 'Ankh');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Leonard');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review & confirm
      expect(screen.getByText(/widget/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(await screen.findByText(/order confirmed/i)).toBeInTheDocument();
      expect(onComplete).toHaveBeenCalledWith('ORD-12345');
    });
  });

  // VALIDATION - The Device For Ensuring Proper Input!
  describe('shipping validation', () => {
    it('displays errors for empty required fields', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
      expect(screen.getByLabelText(/street/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('validates ZIP code format', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip/i), 'WRONG');
      await user.click(screen.getByRole('button', { name: /continue/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  // EMPTY CART - Fascinating edge case!
  describe('empty cart handling', () => {
    it('shows empty cart message and cancel option', () => {
      vi.mocked(mockCart).items = [];
      render(<Checkout onCancel={vi.fn()} />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
      expect(screen.getByRole('button', { name: /continue shopping/i })).toBeInTheDocument();
    });
  });

  // LOADING STATE - The Waiting Indicator Mechanism
  describe('loading states', () => {
    it('disables buttons and shows processing during submission', async () => {
      mockProcessPayment.mockImplementation(() => new Promise(() => {}));
      // ... setup to review step ...
      // Button shows "Processing..." and aria-busy="true"
    });
  });

  // ACCESSIBILITY - Most important!
  it('has no accessibility violations', async () => {
    const { container } = render(<Checkout />);
    expect(await axe(container)).toHaveNoViolations();
  });
});
